create extension if not exists pgcrypto;
create table if not exists public.profiles (id uuid primary key references auth.users(id) on delete cascade,username text unique not null check(username in ('thugger','vichka')),display_name text not null,avatar_url text,updated_at timestamptz default now());
create table if not exists public.photos (id uuid primary key default gen_random_uuid(),title text not null,description text,category text not null,image_url text not null,storage_path text,created_by uuid references auth.users(id),created_at timestamptz default now());
create table if not exists public.movies (id uuid primary key default gen_random_uuid(),title text not null,poster_url text,status text not null default 'watched' check(status in ('watched','planned')),thugger_rating int check(thugger_rating between 1 and 10),vichka_rating int check(vichka_rating between 1 and 10),comment text,favorite_moments text,created_by uuid references auth.users(id),created_at timestamptz default now());
create table if not exists public.artifacts (id uuid primary key default gen_random_uuid(),title text not null,description text,file_url text,link_url text,created_by uuid references auth.users(id),created_at timestamptz default now());
create table if not exists public.pet_state (id int primary key default 1 check(id=1),food int default 72,water int default 84,joy int default 91,sleep int default 64,love int default 37,updated_at timestamptz default now());
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path=public as $$ declare handle text := split_part(new.email,'@',1); begin if handle not in ('thugger','vichka') then raise exception 'Private application'; end if; insert into public.profiles(id,username,display_name) values(new.id,handle,case when handle='vichka' then 'Викуся' else 'thugger' end); return new; end; $$;
drop trigger if exists on_auth_user_created on auth.users;
create trigger on_auth_user_created after insert on auth.users for each row execute procedure public.handle_new_user();
alter table public.profiles enable row level security; alter table public.photos enable row level security; alter table public.movies enable row level security; alter table public.artifacts enable row level security; alter table public.pet_state enable row level security;
create policy "couple profiles read" on public.profiles for select to authenticated using(true); create policy "own profile update" on public.profiles for update to authenticated using(auth.uid()=id) with check(auth.uid()=id);
create policy "couple photos all" on public.photos for all to authenticated using(true) with check(true); create policy "couple movies all" on public.movies for all to authenticated using(true) with check(true); create policy "couple artifacts all" on public.artifacts for all to authenticated using(true) with check(true); create policy "couple pet all" on public.pet_state for all to authenticated using(true) with check(true);
insert into public.pet_state(id) values(1) on conflict do nothing;
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('memories','memories',true,52428800,array['image/jpeg','image/png','image/webp','image/gif','application/pdf']) on conflict(id) do update set public=true;
create policy "couple upload memories" on storage.objects for insert to authenticated with check(bucket_id='memories'); create policy "couple change memories" on storage.objects for update to authenticated using(bucket_id='memories'); create policy "couple delete memories" on storage.objects for delete to authenticated using(bucket_id='memories'); create policy "public read memories" on storage.objects for select using(bucket_id='memories');
